#include <stdio.h>

int main(void)
{
    FILE *input = fopen("input.txt", "rb");
    if (input == NULL) {
        puts("open-input-error");
        return 1;
    }

    unsigned char bytes[64];
    size_t length = 0;
    const char *problem = NULL;
    int byte;
    while ((byte = fgetc(input)) != EOF) {
        if (length == sizeof bytes) {
            problem = "input-too-long";
            break;
        }
        bytes[length++] = (unsigned char)byte;
    }
    if (problem == NULL && ferror(input)) {
        problem = "read-error";
    }
    if (fclose(input) == EOF && problem == NULL) {
        problem = "close-input-error";
    }
    if (problem != NULL) {
        puts(problem);
        return 1;
    }

    FILE *output = fopen("copy.txt", "wb");
    if (output == NULL) {
        puts("open-output-error");
        return 1;
    }
    if (fwrite(bytes, 1, length, output) != length) {
        problem = "write-error";
    }
    if (fclose(output) == EOF && problem == NULL) {
        problem = "close-output-error";
    }
    if (problem != NULL) {
        puts(problem);
        return 1;
    }

    printf("written %zu\n", length);
    return 0;
}

